namespace Harp.Toolkit.Web.Generation;

/// <summary>
/// Represents a device registered in the Harp whoami registry, as listed in devices.json.
/// </summary>
/// <remarks>
/// The catalog is generated by scripts/UpdateDevices.cs and refreshed hourly by CI.
/// </remarks>
public sealed record DeviceEntry(string Name, int WhoAmI, string RepositoryUrl, string DeviceUrl, string? IosUrl = null);

/// <summary>
/// Provides helpers for loading metadata files from links.
/// </summary>
public static class MetadataLinks
{
    /// <summary>
    /// Converts a GitHub page link to a file into a link to its raw contents, so links
    /// copied from the browser address bar can be loaded directly.
    /// </summary>
    public static string ToRawUrl(string url)
    {
        if (!Uri.TryCreate(url.Trim(), UriKind.Absolute, out var uri))
            return url;

        // https://github.com/{owner}/{repo}/blob/{ref}/{path}
        var segments = uri.AbsolutePath.Trim('/').Split('/');
        if (uri.Host == "github.com" && segments.Length > 4 && segments[2] == "blob")
        {
            var path = string.Join('/', segments.Take(2).Concat(segments.Skip(3)));
            return $"https://raw.githubusercontent.com/{path}";
        }

        return uri.ToString();
    }

    /// <summary>
    /// Converts a link to raw file contents on GitHub into the link to its GitHub page,
    /// which is friendlier to read in shared links.
    /// </summary>
    public static string ToPageUrl(string url)
    {
        if (!Uri.TryCreate(url.Trim(), UriKind.Absolute, out var uri) || uri.Host != "raw.githubusercontent.com")
            return url;

        // https://raw.githubusercontent.com/{owner}/{repo}/{ref}/{path}
        var segments = uri.AbsolutePath.Trim('/').Split('/');
        if (segments.Length < 4)
            return url;

        return $"https://github.com/{segments[0]}/{segments[1]}/blob/{string.Join('/', segments.Skip(2))}";
    }

    /// <summary>
    /// Gets a short display name for a metadata file loaded from the specified URL.
    /// </summary>
    public static string GetDisplayName(string url, IEnumerable<DeviceEntry> devices)
    {
        var device = devices.FirstOrDefault(device => device.DeviceUrl == url);
        if (device is not null)
            return device.Name;

        return Uri.TryCreate(url, UriKind.Absolute, out var uri)
            ? uri.Segments.LastOrDefault()?.Trim('/') ?? url
            : url;
    }
}
